#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-2.0-or-later
"""Pin every download of the andarium-accessibility build as an archive row.

dependencies/build-andarium-accessibility.sh builds TalkBack and eSpeak NG
with Gradle offline, from the archives that `dependencies/prepare.sh
--archive-manifest dependencies/andarium-accessibility/archives.tsv` fetched
and verified: the two Gradle distributions and every Maven artifact either
build resolves. This tool writes that list. Run it when a pin moves (a source,
a series or a Gradle version), after one online build of each application
with `--write-verification-metadata sha256` in a fresh Gradle user home,
whose gradle/verification-metadata.xml files are its input:

    pin-archives.py --metadata TALKBACK.xml --metadata ESPEAK.xml \\
        --distribution URL=SHA256 [--distribution ...] --output archives.tsv

Gradle records each artifact's SHA-256 but not where it came from, so the
tool fetches the file from the repositories the builds name and keeps the
first whose bytes have that SHA-256: one coordinate can name different bytes
in two repositories. This is the tool's only use of the network. A
file Gradle names after its variant (a Kotlin multiplatform library's
metadata jar) lives where the component's .module file points, which is where
an offline build looks for it too. A Maven artifact's row is named
maven~GROUP~MODULE~VERSION~FILE after where it lives, which the builder lays
out as a Maven repository.
"""

from __future__ import annotations

__import__("sys").dont_write_bytecode = True

import argparse
import concurrent.futures
import hashlib
import json
import re
import sys
import urllib.error
import urllib.parse
import urllib.request
import xml.etree.ElementTree as ElementTree
from pathlib import Path

REPOSITORIES = (
    "https://dl.google.com/dl/android/maven2",
    "https://repo.maven.apache.org/maven2",
    "https://plugins.gradle.org/m2",
)
NAMESPACE = "{https://schema.gradle.org/dependency-verification}"
NAME = re.compile(r"[A-Za-z0-9][A-Za-z0-9._+%~-]*")
HEADER = """# SPDX-License-Identifier: GPL-2.0-or-later
# Every download of dependencies/build-andarium-accessibility.sh: the Gradle
# distributions and each Maven artifact the TalkBack and eSpeak NG builds
# resolve. Generated by dependencies/andarium-accessibility/pin-archives.py;
# regenerate it rather than editing it. dependencies/prepare.sh
# --archive-manifest fetches and verifies the rows, and the builder runs
# Gradle offline from them.
"""


def fail(message: str) -> None:
    raise SystemExit(f"pin-archives.py: {message}")


def artifacts(metadata: Path) -> set[tuple[str, str, str, str, str]]:
    """(group, module, version, file, sha256) of each artifact the file lists."""
    found = set()
    root = ElementTree.parse(metadata).getroot()
    for component in root.iter(f"{NAMESPACE}component"):
        group, module, version = (component.get(key) for key in ("group", "name", "version"))
        for artifact in component.findall(f"{NAMESPACE}artifact"):
            digest = artifact.find(f"{NAMESPACE}sha256")
            if digest is None:
                fail(f"{metadata}: {group}:{module}:{version} {artifact.get('name')} has no sha256")
            found.add((group, module, version, artifact.get("name"), digest.get("value")))
    if not found:
        fail(f"{metadata} lists no artifact")
    return found


def serves(url: str, digest: str) -> bool:
    """Whether `url` serves bytes whose SHA-256 is `digest`."""
    request = urllib.request.Request(url, headers={"User-Agent": "kernarium-pin-archives"})
    try:
        with urllib.request.urlopen(request, timeout=120) as response:
            sha256 = hashlib.sha256()
            for block in iter(lambda: response.read(1 << 20), b""):
                sha256.update(block)
            return sha256.hexdigest() == digest
    except urllib.error.HTTPError as error:
        if error.code in (403, 404):
            return False
        raise


def module_file(url: str) -> dict | None:
    request = urllib.request.Request(url, headers={"User-Agent": "kernarium-pin-archives"})
    try:
        with urllib.request.urlopen(request, timeout=30) as response:
            return json.load(response)
    except urllib.error.HTTPError as error:
        if error.code in (403, 404):
            return None
        raise


def locate(entry: tuple[str, str, str, str, str]) -> str:
    """The URL of the file, directly under its component or where the
    component's Gradle module metadata points."""
    group, module, version, file, digest = entry
    directory = f"{group.replace('.', '/')}/{module}/{version}"
    for repository in REPOSITORIES:
        if serves(f"{repository}/{directory}/{file}", digest):
            return f"{repository}/{directory}/{file}"
    for repository in REPOSITORIES:
        metadata_url = f"{repository}/{directory}/{module}-{version}.module"
        metadata = module_file(metadata_url)
        if metadata is None:
            continue
        for variant in metadata.get("variants", []):
            for variant_file in variant.get("files", []):
                if variant_file.get("name") == file:
                    url = urllib.parse.urljoin(metadata_url, variant_file["url"])
                    if serves(url, digest):
                        return url
    fail(f"no repository serves {directory}/{file} with its SHA-256")
    return ""


def archive_name(url: str) -> str:
    """maven~GROUP~MODULE~VERSION~FILE for where the file lives."""
    for repository in REPOSITORIES:
        if url.startswith(repository + "/"):
            parts = url[len(repository) + 1:].split("/")
            if len(parts) >= 4:
                return "maven~" + "~".join([".".join(parts[:-3]), *parts[-3:]])
    fail(f"not a repository path: {url}")
    return ""


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("--metadata", type=Path, action="append", required=True,
                        help="a gradle/verification-metadata.xml written with sha256")
    parser.add_argument("--distribution", action="append", default=[],
                        help="URL=SHA256 of a Gradle distribution")
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()

    entries = set()
    for metadata in args.metadata:
        entries |= artifacts(metadata)
    rows: list[tuple[str, str, str]] = []
    for distribution in args.distribution:
        url, _, digest = distribution.partition("=")
        if not url.startswith("https://") or not re.fullmatch(r"[0-9a-f]{64}", digest):
            fail(f"--distribution needs HTTPS_URL=SHA256: {distribution}")
        rows.append((url.rsplit("/", 1)[1], url, digest))
    ordered = sorted(entries)
    with concurrent.futures.ThreadPoolExecutor(max_workers=16) as pool:
        urls = list(pool.map(locate, ordered))
    pinned: dict[str, tuple[str, str]] = {}
    for (_, _, _, _, digest), url in zip(ordered, urls):
        name = archive_name(url)
        if not NAME.fullmatch(name):
            fail(f"an artifact's name cannot be an archive name: {name}")
        if name in pinned and pinned[name] != (url, digest):
            fail(f"two artifacts live at {url} with different contents")
        pinned[name] = (url, digest)
    rows += [(name, url, digest) for name, (url, digest) in sorted(pinned.items())]
    names = [row[0] for row in rows]
    if len(names) != len(set(names)):
        fail("two archives share a name")
    lines = [HEADER, "name\turl\tsha256\n"] + [f"{name}\t{url}\t{digest}\n" for name, url, digest in rows]
    args.output.write_text("".join(lines), encoding="utf-8")
    print(f"pin-archives.py: {len(rows)} archives in {args.output}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
